import React from "react";
import Header from "../components/header";
import BoubaayaFooter from "../components/footer";
import LandingPage from "../components/landingimage";
import ProduitsContent from "../components/ProduitsContent";
import ReviewsSection from "../components/ReviewsSection";

export default function Homepage() {
  return (
    <div>
      <Header></Header>
      <LandingPage></LandingPage>
      <ProduitsContent></ProduitsContent>
      <ReviewsSection></ReviewsSection>
      <BoubaayaFooter></BoubaayaFooter>
    </div>
  );
}
